const item = $input.first().json;
const text = String(item.output || '');
const isStruct = (line) => /^(📍|🌬️|☀️|🌦️|🌦|⛅|🌤️|⛈️|🌧️|🌧|⚠️|⚠|🌾|👉|📰|🔎|✅|ℹ️|📋|- |Call:|Change this if|https?:\/\/)/.test(line);
const lines = text.replace(/\r\n/g, '\n').split('\n');
const out = [];
for (const raw of lines) {
  const line = raw.replace(/[ \t]+$/g, '');
  if (line === '') {
    if (out.length === 0 || out[out.length - 1] !== '') out.push('');
    continue;
  }
  if (!isStruct(line) && out.length && out[out.length - 1] !== '' && !isStruct(out[out.length - 1])) {
    out[out.length - 1] += ' ' + line.trim();
  } else {
    out.push(line);
  }
}
const reflowed = out.join('\n');
const escaped = reflowed.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222">' + escaped.replace(/\n/g, '<br>') + '</div>';
return [{ json: { ...item, output: reflowed, html } }];

const item = $input.first().json;
let text = String(item.output || item.text || '').trim();
const num = (v) => (Array.isArray(v) ? v[0] : v);
const asNum = (v) => {
  const n = Number(num(v));
  return Number.isFinite(n) ? n : null;
};
if (text && !/(☀️|☀|🌦️|🌦|⛅|🌤️|⛈️|🌧️|🌧)/.test(text)) {
  const f = $('Get forecast').first().json || {};
  const c = f.current || {};
  const d = f.daily || {};
  const block = '☀️ Weather\nIt is ' + c.temperature_2m + ' C now, humidity ' + c.relative_humidity_2m + ' %, wind ' + c.wind_speed_10m + ' km/h, rain ' + num(d.precipitation_sum) + ' mm.\nToday\'s high is ' + num(d.temperature_2m_max) + ' C and the low is ' + num(d.temperature_2m_min) + ' C.';
  if (/🌾/.test(text)) {
    text = text.replace(/\n+(?=🌾)/, '\n\n' + block + '\n\n');
  } else if (/👉/.test(text)) {
    text = text.replace(/\n+(?=👉)/, '\n\n' + block + '\n\n');
  } else {
    text = text + '\n\n' + block;
  }
}
if (text && !/⚠️|⚠/.test(text)) {
  let first = 'Official Meteoalarm warnings were not available for this run.';
  try {
    const s = String((($('Compact alerts').first() || {}).json || {}).summary || '');
    const line = s.split('\n').filter(Boolean)[0];
    if (line) first = line;
  } catch (e) {}
  const block = '⚠️ Official alert\n' + first;
  if (/🌾/.test(text)) {
    text = text.replace(/\n+(?=🌾)/, '\n\n' + block + '\n\n');
  } else if (/👉/.test(text)) {
    text = text.replace(/\n+(?=👉)/, '\n\n' + block + '\n\n');
  } else {
    text = text + '\n\n' + block;
  }
}
const air = (($('Get CAMS air').first() || {}).json || {}).current || {};
const pm25 = asNum(air.pm2_5);
const aqi = asNum(air.european_aqi);
const call = (text.match(/Call:\s*(open|close|filter|stay)/i) || [])[1] || '';
const alreadyTrue = (line) => {
  const worse = /(exceeds|above|over|higher than|rises above)/i.test(line);
  const better = /(falls below|drops below|below)/i.test(line);
  const pm = line.match(/PM2\.5[^\d]{0,48}(\d+(?:\.\d+)?)|(\d+(?:\.\d+)?)[^\d]{0,24}ug\/m3/i);
  const aq = line.match(/(?:European\s+)?AQI[^\d]{0,48}(\d+(?:\.\d+)?)/i);
  const pmVal = pm ? Number(pm[1] || pm[2]) : null;
  const aqVal = aq ? Number(aq[1]) : null;
  let hit = false;
  if (pm25 != null && pmVal != null) {
    if (worse && pm25 >= pmVal) hit = true;
    if (better && pm25 <= pmVal) hit = true;
  }
  if (aqi != null && aqVal != null) {
    if (worse && aqi >= aqVal) hit = true;
    if (better && aqi <= aqVal) hit = true;
  }
  return hit;
};
const fallback = () => {
  if (/stay|close/i.test(call)) {
    return 'Change this if: modelled PM2.5 falls below 35 ug/m3 and European AQI falls below 50, or a local official service says outdoor air has cleared.';
  }
  const nextPm = pm25 == null ? 35 : Math.max(35, Math.ceil(pm25) + 15);
  const nextAqi = aqi == null ? 80 : Math.max(80, Math.ceil(aqi / 10) * 10 + 20);
  return 'Change this if: European AQI rises above ' + nextAqi + ' or PM2.5 exceeds ' + nextPm + ' ug/m3.';
};
text = text.replace(/^Change this if:.+$/im, (line) => (alreadyTrue(line) ? fallback() : line));
const NOTE = 'ℹ️ Note\nThis is not a medical diagnosis. Outdoor figures are modelled (CAMS via Open-Meteo), not a street station. Official weather warnings come from Meteoalarm when listed above; check your national meteorological service, and talk to a doctor if you or anyone in your care feels unwell.';
if (text && !/ℹ️|ℹ/.test(text)) {
  text = text.replace(/\s*$/, '') + '\n\n' + NOTE;
}
return [{ json: { ...item, output: text } }];

try {
  const place = $('Set Place').first().json || {};
  const name = String(place.name || '').trim();
  const country = String(place.country || '').trim();
  const item = $input.first().json || {};
  let xml = String(item.data || item.body || '');
  if (!xml.includes('<feed') && !xml.includes('<entry') && item && typeof item === 'object') {
    for (const v of Object.values(item)) {
      if (typeof v === 'string' && (v.includes('<feed') || v.includes('<entry'))) { xml = v; break; }
    }
  }
  const raw = country.toLowerCase();
  const aliases = { uk: 'united-kingdom', 'united kingdom': 'united-kingdom', 'great britain': 'united-kingdom', 'czech republic': 'czechia', 'the netherlands': 'netherlands', usa: '', 'united states': '' };
  const slug = Object.prototype.hasOwnProperty.call(aliases, raw) ? aliases[raw] : raw.replace(/\s+/g, '-');
  if (!xml.includes('<entry') && !xml.includes('<feed')) {
    const summary = slug
      ? 'Meteoalarm returned no usable feed for ' + country + '. Treat official alerts as unavailable. Do not invent a warning.'
      : 'Meteoalarm does not cover ' + (country || 'this country') + '. Official European warnings are unavailable here.';
    return [{ json: { summary, localCount: 0, countryCount: 0 } }];
  }
  const tag = (block, names) => {
    for (const n of names) {
      const m = block.match(new RegExp('<(?:cap:)?' + n + '>([\\s\\S]*?)</(?:cap:)?' + n + '>', 'i'));
      if (m) return m[1].replace(/<[^>]+>/g, '').trim();
    }
    return '';
  };
  const now = Date.now();
  const entries = [];
  for (const rawEntry of xml.split(/<entry[\\s>]/i).slice(1)) {
    const block = '<entry>' + rawEntry;
    const expires = tag(block, ['expires']);
    const expMs = Date.parse(expires);
    if (Number.isFinite(expMs) && expMs < now) continue;
    const title = tag(block, ['title']);
    const area = tag(block, ['areaDesc']);
    const event = tag(block, ['event']);
    const severity = tag(block, ['severity']);
    if (!title && !event) continue;
    entries.push({ title, area, event, severity, expires });
  }
  const placeAliases = { seville: ['seville', 'sevilla'], sevilla: ['seville', 'sevilla'] };
  const key = name.toLowerCase();
  const tokens = (placeAliases[key] || [key]).concat(key.split(/\s+/)).filter((t) => t.length >= 4);
  const local = entries.filter((e) => {
    const hay = (e.area + ' ' + e.title).toLowerCase();
    return tokens.some((t) => hay.includes(t));
  });
  const pick = (local.length ? local : entries).slice(0, 6);
  const line = (e) => [e.severity, e.event || e.title, e.area, e.expires ? ('until ' + e.expires) : ''].filter(Boolean).join(' | ');
  let summary;
  if (!entries.length) {
    summary = 'No current Meteoalarm warning for ' + country + '. Say there is no official warning for this country today. Source: Meteoalarm.';
  } else if (local.length) {
    summary = 'Official Meteoalarm warnings that match ' + name + ', ' + country + ':\n' + pick.map(line).join('\n');
  } else {
    summary = 'No Meteoalarm warning named for ' + name + '. ' + country + ' currently has ' + entries.length + ' warning(s). Country sample (not local):\n' + pick.map(line).join('\n');
  }
  return [{ json: { summary, localCount: local.length, countryCount: entries.length } }];
} catch (e) {
  return [{ json: { summary: 'Official Meteoalarm warnings were unavailable this run. Do not invent a warning.', localCount: 0, countryCount: 0 } }];
}
